// The exact Windows Process handle remains open across all identity checks,
// Kill and WaitForExit. The durable daemon exit is written before returning.
export const HISTORICAL_PRELAUNCH_HANDLE_PROGRAM=String.raw`
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false)
[Console]::InputEncoding=[System.Text.UTF8Encoding]::new($false)
$d=([Console]::In.ReadToEnd()|ConvertFrom-Json)
function Assert-Fact($v){if(!$v){throw 'Historical recovery identity or evidence changed'}}
function File-Hash($f){$h=[Security.Cryptography.SHA256]::Create();try{return [BitConverter]::ToString($h.ComputeHash([IO.File]::ReadAllBytes($f))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Text-Hash($v){$h=[Security.Cryptography.SHA256]::Create();try{return [BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($v))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function No-Link($f){$i=Get-Item -LiteralPath $f -Force;while($i){Assert-Fact (($i.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0);$parent=Split-Path -Parent $i.FullName;if(!$parent -or $parent -eq $i.FullName){break};$i=Get-Item -LiteralPath $parent -Force}}
$p=Get-Process -Id $d.pid -ErrorAction Stop
try{
 $heldHandle=$p.Handle
 $native=Get-CimInstance Win32_Process -Filter ('ProcessId = '+$d.pid)
 Assert-Fact ($native -and $native.CreationDate.ToUniversalTime().ToString('o') -ceq $d.creationTime)
 Assert-Fact ([Math]::Abs(($p.StartTime.ToUniversalTime()-$native.CreationDate.ToUniversalTime()).TotalMilliseconds) -le 2)
 Assert-Fact ($native.ExecutablePath -ieq $d.executable -and (Text-Hash $native.CommandLine) -ceq $d.commandHash)
 $listeners=@(Get-NetTCPConnection -State Listen -LocalPort $d.port|Where-Object {$_.LocalAddress -eq $d.host})
 Assert-Fact ($listeners.Count -eq 1 -and $listeners[0].OwningProcess -eq $d.pid)
 No-Link $d.configPath
 Assert-Fact ((File-Hash $d.configPath) -ceq $d.configSha256)
 $request=[Net.HttpWebRequest]::Create($d.origin+'/healthz');$request.Proxy=$null;$request.Timeout=3000;$response=$request.GetResponse()
 try{$reader=[IO.StreamReader]::new($response.GetResponseStream());try{$health=$reader.ReadToEnd()|ConvertFrom-Json}finally{$reader.Dispose()}}finally{$response.Dispose()}
 Assert-Fact ($health.service -ceq 'ziwei_user' -and $health.agentId -ceq 'ziwei_user' -and $health.pid -eq $d.pid -and $health.clientBuild -ceq $d.build -and $health.workspace -ceq $d.workspace -and $health.deviceId -ceq $d.deviceId)
 Assert-Fact ($health.connectionState -ceq 'draining' -and $health.activeActionCount -eq 1 -and $health.pollingCount -eq 0 -and $health.quarantinedActionCount -eq 1 -and $health.executionQuarantined -eq $true)
 Assert-Fact ($health.lifecycle.nonce -ceq $d.nonce -and $health.lifecycle.root -ieq $d.root -and $health.lifecycle.configPath -ieq $d.configPath -and $health.lifecycle.configSha256 -ceq $d.configSha256 -and $health.lifecycle.runtimeDir -ieq $d.runtimeDir -and $health.lifecycle.startedAt -ceq $d.startedAt -and $health.lifecycle.managedAuxiliaryCount -eq 0)
 Assert-Fact ($health.maintenance.safe -eq $false -and $health.maintenance.stopSafe -eq $false -and $health.maintenance.gatewaySafe -eq $true -and $health.maintenance.gatewayWorkers -is [Array] -and @($health.maintenance.gatewayWorkers).Count -eq 0 -and $health.maintenance.pendingDeliveryCount -eq 0 -and $health.maintenance.blockedDeliveryCount -eq 0 -and $health.maintenance.retainedDeliveryCount -eq 0)
 Assert-Fact ($health.maintenance.fileIssues -is [Array] -and @($health.maintenance.fileIssues).Count -eq 2 -and @($health.maintenance.fileIssues|Where-Object {$_.actionId -cne $d.actionId -or @('STARTED_WITHOUT_RESULT','DELIVERY_NOT_DRAINED') -cnotcontains $_.code}).Count -eq 0)
 Assert-Fact ($health.maintenance.stopIssues -is [Array] -and @($health.maintenance.stopIssues).Count -eq 2 -and @($health.maintenance.stopIssues|Where-Object {@('STARTED_WITHOUT_RESULT','DELIVERY_NOT_DRAINED') -cnotcontains $_.code}).Count -eq 0)
 foreach($item in $d.directories){if(!$item.exists){Assert-Fact (!(Test-Path -LiteralPath $item.path));continue};No-Link $item.path;$actual=@(Get-ChildItem -LiteralPath $item.path -Force|ForEach-Object {$_.Name}|Sort-Object);$expected=@($item.names|Sort-Object);Assert-Fact ($actual.Count -eq $expected.Count);for($i=0;$i -lt $actual.Count;$i++){Assert-Fact ($actual[$i] -ceq $expected[$i])}}
 foreach($item in $d.files){if(!$item.exists){Assert-Fact (!(Test-Path -LiteralPath $item.path));continue};No-Link $item.path;Assert-Fact ((File-Hash $item.path) -ceq $item.sha256)}
 Assert-Fact ((File-Hash $d.configPath) -ceq $d.configSha256)
 Assert-Fact (@(Get-CimInstance Win32_Process -Filter ('ParentProcessId = '+$d.pid)).Count -eq 0)
 Assert-Fact (!$p.HasExited)
 $p.Kill()
 Assert-Fact ($p.WaitForExit($d.waitMs) -and $p.HasExited)
 $exit=[pscustomobject]@{stopped=$true;pid=[int]$d.pid;creationTime=$d.creationTime;exitedAt=[DateTime]::UtcNow.ToString('o')}
 No-Link (Split-Path -Parent $d.exitFile)
 $bytes=[Text.Encoding]::UTF8.GetBytes(($exit|ConvertTo-Json -Compress));$stream=[IO.File]::Open($d.exitFile,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
 try{$stream.Write($bytes,0,$bytes.Length);$stream.Flush($true)}finally{$stream.Dispose()}
 $exit|ConvertTo-Json -Compress
}finally{$p.Dispose()}
`;
